CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "user_profile" ("id" integer primary key autoincrement not null, "name" text not null, "email" text not null, "password" text, "blocked" tinyint(1) not null default '0', "is_admin" tinyint(1) not null default '0', "remember_token" text, "email_verified_at" datetime, "profile_picture_path" text);
CREATE UNIQUE INDEX "user_profile_email_unique" on "user_profile" ("email");
CREATE TABLE "oauth_user" ("id" integer primary key autoincrement not null, "user_id" integer not null, "provider_type" varchar check ("provider_type" in ('github', 'google')) not null, "provider_token" text not null, "provider_refresh_token" text, foreign key("user_id") references "user_profile"("id") on delete cascade);
CREATE UNIQUE INDEX "oauth_user_provider_type_provider_token_unique" on "oauth_user" ("provider_type", "provider_token");
CREATE TABLE "project" ("id" integer primary key autoincrement not null, "name" text not null, "description" text, "creation_date" datetime not null default CURRENT_TIMESTAMP, "edit_date" datetime, "archived" tinyint(1) not null default '0', "coordinator_id" integer not null, foreign key("coordinator_id") references "user_profile"("id") on delete restrict);
CREATE TABLE "task_group" ("id" integer primary key autoincrement not null, "name" text not null, "description" text, "creation_date" datetime not null default CURRENT_TIMESTAMP, "position" integer not null, "project_id" integer not null, foreign key("project_id") references "project"("id") on delete cascade);
CREATE UNIQUE INDEX "task_group_position_project_id_unique" on "task_group" ("position", "project_id");
CREATE INDEX "task_group_project" on "task_group" ("project_id", "position");
CREATE TABLE "project_timeline_action" ("id" integer primary key autoincrement not null, "timestamp" datetime not null default CURRENT_TIMESTAMP, "description" text not null, "project_id" integer not null, foreign key("project_id") references "project"("id") on delete cascade);
CREATE TABLE "task" ("id" integer primary key autoincrement not null, "name" text not null, "description" text, "creation_date" datetime not null default CURRENT_TIMESTAMP, "edit_date" datetime, "completed" tinyint(1) not null default '0', "creator_id" integer, "position" integer not null, "task_group_id" integer not null, foreign key("creator_id") references "user_profile"("id") on delete set null, foreign key("task_group_id") references "task_group"("id") on delete cascade);
CREATE UNIQUE INDEX "task_position_task_group_id_unique" on "task" ("position", "task_group_id");
CREATE INDEX "task_task_group" on "task" ("task_group_id", "position");
CREATE TABLE "task_comment" ("id" integer primary key autoincrement not null, "content" text not null, "creation_date" datetime not null default CURRENT_TIMESTAMP, "edit_date" datetime, "author_id" integer, "task_id" integer not null, foreign key("author_id") references "user_profile"("id") on delete set null, foreign key("task_id") references "task"("id") on delete cascade);
CREATE TABLE "tag" ("id" integer primary key autoincrement not null, "title" text not null, "description" text, "color" integer not null, "project_id" integer not null, foreign key("project_id") references "project"("id") on delete cascade);
CREATE TABLE "thread" ("id" integer primary key autoincrement not null, "title" text not null, "content" text not null, "creation_date" datetime not null default CURRENT_TIMESTAMP, "edit_date" datetime, "author_id" integer, "project_id" integer not null, foreign key("author_id") references "user_profile"("id") on delete set null, foreign key("project_id") references "project"("id") on delete cascade);
CREATE TABLE "thread_comment" ("id" integer primary key autoincrement not null, "content" text not null, "creation_date" datetime not null default CURRENT_TIMESTAMP, "edit_date" datetime, "thread_id" integer not null, "author_id" integer, foreign key("thread_id") references "thread"("id") on delete cascade, foreign key("author_id") references "user_profile"("id") on delete set null);
CREATE TABLE "notification" ("id" integer primary key autoincrement not null, "type" text not null, "json" text not null, "creation_date" datetime not null default CURRENT_TIMESTAMP, "read_date" datetime, "notifiable_id" integer not null, foreign key("notifiable_id") references "user_profile"("id") on delete cascade);
CREATE INDEX "notification_search_idx" on "notification" ("notifiable_id");
CREATE TABLE "report" ("id" integer primary key autoincrement not null, "creation_date" datetime not null default CURRENT_TIMESTAMP, "reason" text not null, "project_id" integer, "user_profile_id" integer, "creator_id" integer, foreign key("project_id") references "project"("id") on delete cascade, foreign key("user_profile_id") references "user_profile"("id") on delete cascade, foreign key("creator_id") references "user_profile"("id") on delete set null);
CREATE TABLE "project_member" ("user_profile_id" integer not null, "project_id" integer not null, "is_favorite" tinyint(1) not null default '0', foreign key("user_profile_id") references "user_profile"("id") on delete cascade, foreign key("project_id") references "project"("id") on delete cascade, primary key ("user_profile_id", "project_id"));
CREATE TABLE "task_assignee" ("user_profile_id" integer not null, "task_id" integer not null, foreign key("user_profile_id") references "user_profile"("id") on delete cascade, foreign key("task_id") references "task"("id") on delete cascade, primary key ("user_profile_id", "task_id"));
CREATE TABLE "task_tag" ("task_id" integer not null, "tag_id" integer not null, foreign key("task_id") references "task"("id") on delete cascade, foreign key("tag_id") references "tag"("id") on delete cascade, primary key ("task_id", "tag_id"));
CREATE TABLE "password_resets" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
INSERT INTO migrations (migration, batch) VALUES ("2026_09_13_000001_create_core_schema", 1);
